class Statistics3:
    """
    This is a class that implements methods for calculating indicators such as median, mode, correlation matrix, and Z-score in statistics.
    """

    @staticmethod
    def mean(data):
        """
        calculates the mean of the given list.
        """
        if not data:
            return 0.0
        return sum(data) / len(data)

    @staticmethod
    def median(data):
        """
        calculates the median of the given list.
        """
        if not data:
            return 0.0
        sorted_data = sorted(data)
        n = len(sorted_data)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_data[mid - 1] + sorted_data[mid]) / 2.0
        return float(sorted_data[mid])

    @staticmethod
    def mode(data):
        """
        calculates the mode of the given list.
        """
        if not data:
            return []
        counts = Counter(data)
        max_freq = max(counts.values())
        return sorted([k for k, v in counts.items() if v == max_freq])

    @staticmethod
    def standard_deviation(data):
        """
        calculates the standard deviation of the given list.
        """
        if len(data) < 2:
            return 0.0
        avg = Statistics3.mean(data)
        variance = sum((x - avg) ** 2 for x in data) / (len(data) - 1)
        return math.sqrt(variance)

    @staticmethod
    def correlation(x, y):
        """
        calculates the correlation of the given list.
        """
        if len(x) != len(y) or len(x) < 2:
            return 0.0

        mean_x = Statistics3.mean(x)
        mean_y = Statistics3.mean(y)

        numerator = sum((x[i] - mean_x) * (y[i] - mean_y) for i in range(len(x)))
        sum_sq_diff_x = sum((xi - mean_x) ** 2 for xi in x)
        sum_sq_diff_y = sum((yi - mean_y) ** 2 for yi in y)

        denominator = math.sqrt(sum_sq_diff_x * sum_sq_diff_y)
        return numerator / denominator if denominator != 0 else 0.0

    @staticmethod
    def correlation_matrix(data):
        """
        calculates the correlation matrix of the given list.
        """
        n = len(data)
        matrix = [[0.0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                matrix[i][j] = Statistics3.correlation(data[i], data[j])
        return matrix

    @staticmethod
    def z_score(data):
        """
        calculates the z-score of the given list.
        """
        if len(data) < 2:
            return [0.0 for _ in data]
        avg = Statistics3.mean(data)
        std = Statistics3.standard_deviation(data)
        if std == 0:
            return [0.0 for _ in data]
        return [(x - avg) / std for x in data]

